# Key/value arrays
#
# This modules implements arrays of key/value pairs. The keys are specified
# relationally so that one can write properties such as "for every key satisfying
# predicate p, there exists an element having that key". On the other hand, the
# values are specified funcitonally, so one can easily retreive the value associated
# to a particular key.
#
# The parameters of this module are:
#
# index : the index structure, as in "array"
# key : the key type
# data : the value type
#
# The available methods are:
#
# empty : returns an empty array
# end : returns the index one after the last element
# get_key : gets the key at an index
# get_value : gets the value at and index
# append_pair : appends a key/value pair
#
# Typical code to look up the value of a key k in array a would be:
#
# if some (i : index.t) a.key_at(i,k) {
#     var v := a.value_at(i);
#     ... use value v ...
# } else {
#     ... k is not present ...
# }

module keyval(index,key,data) = {

    type this
    alias t=this 

    function end(A:t) : index.t
    relation key_at(A:t, I:index.t, X:key)
    function value_at(A:t, I:index.t) : data

    action empty returns (s:t)
    action get_key(s:t, i:index.t) returns (k:key)
    action get_value(s:t, i:index.t) returns (d:data)
    action append_pair(s:t, k:key, d:data) returns (s:t)
    action get(s:t,k:key,d:data) returns (d:data)
    action find(s:t,k:key) returns (i:index.t)
    action remove(s:t,k:key) returns (s:t)
    action set(s:t,k:key,d:data) returns (s:t)

    object spec = {

        property key_at(A,I,X) -> 0 <= I & I < end(A)
        property key_at(A,I,X) & key_at(A,I,Y) -> X = Y
        property 0 <= end(A) 

        after empty {
            assert s.end = 0 & ~key_at(s,I,X)
        }
        before get_key {
            assert 0 <= i & i < s.end
        }
        after get_key {
            assert key_at(s,i,k)
        }
        before get_value {
            assert 0 <= i & i < s.end
        }
        after get_value {
            assert value_at(s,i) = d
        }
        after append_pair {
            assert key_at(s,I,X) <-> key_at(old s,I,X) | I = end(old s) & X = k;
            assert key_at(old s,I,X) -> value_at(s,I) = value_at(old s,I);
            assert value_at(s,end(old s)) = d
        }
    }

    object impl = {

        type pair = struct {
            p_key : key,
            p_value : data
        }

        instance arr : array(index.t,pair)

        destructor repr(X:t) : arr.t

        definition end(A:t) = repr(A).end
        definition value_at(A,I) = repr(A).value(I).p_value
        definition key_at(A,I,X) = (0 <= I & I < end(A) & repr(A).value(I).p_key = X)

        implement empty {
            repr(s) := arr.empty
        }
        implement get_key {
            k := repr(s).get(i).p_key
        }
        implement get_value {
            d := repr(s).get(i).p_value
        }
        implement append_pair {
            var p : pair;
            p.p_key := k;
            p.p_value := d;
            repr(s) := repr(s).append(p)
        }
        implement get {
            var i := repr(s).begin;
            var end := repr(s).end;
            while i < end {
                var v := repr(s).value(i);
                if v.p_key = k {
                    d := v.p_value;
                }
                i := i.next;
            }
        }
        implement find {
            i := repr(s).begin;
            var end := repr(s).end;
            while i < end & repr(s).value(i).p_key ~= k {
                i := i.next;
            }
        }

        implement remove {
            var i := s.find(k);
            var end := repr(s).end;
            if i < end {
                repr(s) := repr(s).set(i,repr(s).value(index.prev(repr(s).end)));
                repr(s) := repr(s).pop_back();
            }
        }

        implement set {
            var p : pair;
            p.p_key := k;
            p.p_value := d;
            var i := s.find(k);
            var end := repr(s).end;
            if i < end {
                repr(s) := repr(s).set(i,p);
            } else {
                repr(s) := repr(s).append(p)
            }
        }
    }
    isolate iso = this with index
    attribute test=impl
}

# This module allows you to extract and use segments of an array
# without using arithmetic.


module segment(domain,range,arr) = {

    # Requirements

    # - Type `domain` must support arithmetic.
    # - Type `arr` must be an array type over (`domain`,`range`).

    # This is a type of segments over `arr`

    type this

    # Extract a segment of an array, from a begin index to an end
    # index

    action make(data:arr, begin:domain, end:domain) returns (seg:this)

    # Function to obtain the value of a segment at a given index.

    function value(X:this,N:domain) : range

    specification {

        # When extracting a segment from an array, the range [begin,end) must
        # describe a segment of the array. The return value is a segment representing
        # the range [begin,end) of the array

        # Example:

        #     var a := arr.empty
        #     a := a.append(1);
        #     a := a.append(2);
        #     a := a.append(3);
        #     a := a.append(4);
        #     var s := segment.make(a,1,3);
        #     assert s.value(1) = 2 & s.value(2) = 3;   -- true
        #     assert s.value(0) = 1;                    -- false
        #     assert s.value(3) = 4;                    -- false

        around make {
            require 0 <= begin & begin <= end & end <= data.end
            ...
            ensure begin <= N & N < end -> value(seg,N) = arr.value(data,N)
        }
    }

    implementation {

        # The implementation represents a segment as a pair consisting
        # of an offset into the original array and an array containin
        # the segment values. It constructs segmens in the expected
        # way, by copying array elements in a loop. 

        # We have to use arithmetic to prove the implementation, but
        # this is within the decidable array property fragment.

        # Notice we use domain.impl to prove this isolate, so we get
        # the arithmetic theory.

        destructor offset(X:this) : domain
        destructor elems(X:this) : arr

        definition value(X,N) = elems(X).value(N - offset(X))

        implement make {
            seg.offset := begin;
            seg.elems := arr.empty;
            var idx := begin;
            while idx < end
            invariant begin <= idx & idx <= end
            invariant seg.offset = begin
            invariant begin <= N & N < idx -> seg.value(N) = data.value(N)
            invariant begin + seg.elems.end = idx
            {
                seg.elems := seg.elems.append(data.value(idx));
                idx := idx.next;
            }
        }
    }

    isolate iso = this with domain.impl,arr
}

