        action random (upper:this) returns (res:this)  # not perfectly uniform!
        implementation {
            implement random {
                <<<
                res = 0;
                for (int b = 64; b > 0; b -= 15) {
                    int q = ( b < 15 ) ? b : 15;
                    res = (res << q) | (::random() & ~(-1 << q));
